import{_ as a,o,c as s,a5 as t}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — View Workspace Dashboard (FR 3.4.11)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-11-view-workspace-dashboard/plan.md","filePath":"feature/agency-workspace/3-4-11-view-workspace-dashboard/plan.md"}'),n={name:"feature/agency-workspace/3-4-11-view-workspace-dashboard/plan.md"};function c(d,e,r,i,p,l){return o(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="plan-—-view-workspace-dashboard-fr-3-4-11" tabindex="-1">Plan — View Workspace Dashboard (FR 3.4.11) <a class="header-anchor" href="#plan-—-view-workspace-dashboard-fr-3-4-11" aria-label="Permalink to &quot;Plan — View Workspace Dashboard (FR 3.4.11)&quot;">​</a></h1><p>&gt; Linked: <a href="./spec.html">spec.md</a> — Document status: <strong>Implemented</strong>. This plan describes the real, shipped implementation.</p><h2 id="_1-technical-scope" tabindex="-1">1. Technical Scope <a class="header-anchor" href="#_1-technical-scope" aria-label="Permalink to &quot;1. Technical Scope&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code> (backend), <code>brandhub-web-dashboard</code> (frontend)</td></tr><tr><td>Backend files</td><td><code>WorkspaceServiceImpl.getDashboard()</code>, <code>WorkspaceController.getDashboard()</code>, <code>WorkspaceDashboardResponse</code> (new record)</td></tr><tr><td>Reused files</td><td><code>WorkspaceMemberRepository</code>, <code>WorkspaceMediaPackageRepository</code>, <code>MediaCampaignRepository</code>, <code>AiCreditLedgerRepository</code>, <code>findWorkspaceOrThrow</code>, <code>assertMember</code>, <code>toResponse</code></td></tr><tr><td>Frontend files</td><td><code>src/pages/workspace/dashboard.tsx</code>, <code>src/services/workspaceService.ts</code> (<code>getDashboard</code>), <code>src/types/workspace.ts</code> (<code>WorkspaceDashboard</code>)</td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/workspaces/{workspaceId}/dashboard</span></span>
<span class="line"><span>Authorization: Bearer &lt;access-token&gt;</span></span>
<span class="line"><span>Roles: MANAGER, CREATOR, CLIENT (@RequireRole, active membership required)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 200 ApiResponse&lt;WorkspaceDashboardResponse&gt;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;success&quot;: true,</span></span>
<span class="line"><span>  &quot;data&quot;: {</span></span>
<span class="line"><span>    &quot;workspace&quot;: { ...WorkspaceResponse... },</span></span>
<span class="line"><span>    &quot;totalActiveMembers&quot;: number,</span></span>
<span class="line"><span>    &quot;membersByRole&quot;: { &quot;MANAGER&quot;: number, &quot;CREATOR&quot;: number, &quot;CLIENT&quot;: number },</span></span>
<span class="line"><span>    &quot;totalCampaigns&quot;: number,</span></span>
<span class="line"><span>    &quot;campaignsByStatus&quot;: { &quot;&lt;CampaignStatus&gt;&quot;: number, ... },</span></span>
<span class="line"><span>    &quot;packageNegotiationStatus&quot;: string | null,</span></span>
<span class="line"><span>    &quot;agencyId&quot;: uuid,</span></span>
<span class="line"><span>    &quot;aiCreditMonth&quot;: &quot;YYYY-MM&quot;,</span></span>
<span class="line"><span>    &quot;agencyAiCreditsUsedThisMonth&quot;: number</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Matches <code>WorkspaceDashboardResponse</code> record exactly (<code>com.brandhub.business.dto.response.WorkspaceDashboardResponse</code>). No request body; <code>workspaceId</code> is a path variable, consistent with other Workspace endpoints.</p><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><p>No new entity or migration. The dashboard aggregates existing tables read-only:</p><ul><li><code>WorkspaceMember</code> — active rows for the Workspace (<code>findByWorkspaceIdAndIsActiveTrue</code>), grouped by <code>role</code> for <code>totalActiveMembers</code> / <code>membersByRole</code>.</li><li><code>WorkspaceMediaPackage</code> — the Workspace&#39;s package, if any (<code>findByWorkspaceId</code>); source of <code>packageNegotiationStatus</code> (<code>null</code> when absent).</li><li><code>MediaCampaign</code> — rows under the Workspace&#39;s package (<code>findByWorkspaceMediaPackageId</code>), grouped by <code>status</code> for <code>totalCampaigns</code> / <code>campaignsByStatus</code>. Empty list when there is no package.</li><li><code>AiCreditLedger</code> — the parent Agency&#39;s row for the current calendar month (<code>findByAgencyIdAndMonth(agencyId, YearMonth.now().toString())</code>); Agency-scoped, not per-Workspace (no <code>workspaceId</code> column exists on this table).</li></ul><h2 id="_4-processing-flow" tabindex="-1">4. Processing Flow <a class="header-anchor" href="#_4-processing-flow" aria-label="Permalink to &quot;4. Processing Flow&quot;">​</a></h2><ol><li><code>findWorkspaceOrThrow(workspaceId)</code> → 404 <code>WORKSPACE_NOT_FOUND</code> if missing.</li><li><code>assertMember(workspaceId, currentUser.getId())</code> → 403 <code>WORKSPACE_ACCESS_DENIED</code> if the caller has no active membership row (BR-29). The <code>@RequireRole</code> annotation on the controller adds a second layer, rejecting with 403 <code>FORBIDDEN</code> if the caller has no membership row at all (same dual-layer pattern as <code>getWorkspace</code>, FR 3.4.13).</li><li>Load active members, compute <code>membersByRole</code> via <code>Collectors.groupingBy(role, counting())</code>.</li><li>Load the Workspace&#39;s <code>WorkspaceMediaPackage</code> (nullable); load its campaigns if present, else empty list. Compute <code>campaignsByStatus</code>.</li><li>Compute <code>currentMonth</code> (<code>YearMonth.now().toString()</code>) and look up the Agency&#39;s <code>AiCreditLedger</code> for that month; default <code>creditsUsed</code> to 0 if no ledger row exists yet.</li><li>Assemble and return <code>WorkspaceDashboardResponse</code>, embedding the full <code>WorkspaceResponse</code> (via <code>toResponse</code>) for the Workspace&#39;s own profile fields.</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Direction</th><th>Description</th></tr></thead><tbody><tr><td>Blocked by</td><td>None — all referenced repositories and entities already exist.</td></tr><tr><td>Blocks</td><td>None.</td></tr></tbody></table><h2 id="_6-technical-notes" tabindex="-1">6. Technical Notes <a class="header-anchor" href="#_6-technical-notes" aria-label="Permalink to &quot;6. Technical Notes&quot;">​</a></h2><ul><li>No Task/Material entity exists in this codebase; an earlier draft of this spec assumed one — removed, not implemented (see spec.md &quot;Known scope note&quot;).</li><li>AI credit usage is Agency-wide (<code>AiCreditLedger</code> has no <code>workspaceId</code> column); the response and UI label it explicitly as Agency-scoped rather than implying it belongs to this Workspace alone.</li><li>The dashboard is fully read-only (BR-03); no writes occur in <code>getDashboard</code>.</li><li>An empty Workspace (no package, no campaigns) is handled without error: <code>packageNegotiationStatus</code> is <code>null</code>, <code>totalCampaigns</code> is <code>0</code>, breakdown maps are empty (BR-04).</li></ul>`,16)])])}const b=a(n,[["render",c]]);export{u as __pageData,b as default};
